/**
 * zh.ts — 日本語の画面文言 → 简体中文。**生成物・手で編集しない。**
 *
 *   直すとき: tools/i18n/data/translations/*.json を直して
 *             node tools/i18n/build-dictionary.mjs
 *
 * 鍵は日本語そのもの。理由と使い方は src/lib/ui-text.ts の冒頭。
 * 訳語の正は _specs/i18n-glossary.md — 新しい語はまずあちらに 1 行足す。
 */

