  "「完了通知」を付けた共有先には、申請・報告が完了したとき（承認フローを\n          使うなら全段の承認、使わないなら提出）に通知が届き、承認・予定 (CM01)\n          の「完了した申請」に並びます。条件を付けた共有先には、その条件に\n          当てはまる回答の完了だけが届きます。": "勾选了「完成通知」的共享对象，将在申请・报告完成时（使用审批流程时为全部级别批准，不使用时为提交）收到通知，并列在审批与计划 (CM01) 的「已完成的申请」中。设置了条件的共享对象仅会收到符合该条件的回答的完成通知。",
