  "1 通に並べる件数の上限。超えた分は「ほか N 件」に畳まれます（畳まれた通知も送信済みとして扱われ、次の回には載りません）。": "单封邮件中列出的上限件数。超出部分将折叠为「其他 N 件」（折叠的通知也视为已发送，下次不再列出）。",
