  "この地域は {plantCount} 件の拠点から参照されているため削除できません（先に拠点の地域を変更してください）": "该地区被 {plantCount} 个据点引用，无法删除（请先更改据点的地区）",
  "この注文を主に処理する自社の拠点です。どの拠点の仕事かをはっきりさせたいときに選びます。": "主要处理此订单的本公司据点。需要明确是哪个据点的工作时选择。",
