  "外すと、そのグループでの承認が行われなくなります。メンバーと代理の設定は詳細画面で行います。": "取消后将不再通过该分组审批。成员和代理设置在详情画面进行。",
  "外すと、見積書や価格表の製品の選択肢に出なくなります。": "取消后将不再出现在报价单和价格表的产品选项中。",
  "外すと、見積書や発注書などで新しく選べなくなります。すでにその会社で作った書類はそのまま残ります。": "取消后将无法在报价单和采购单等中新选择。已为该公司创建的单据将保留。",
  "外すと、材種や素材を登録するときの選択肢に出なくなります。使わなくなったメーカーや形状を、過去の登録は残したまま隠すときに使います。": "取消后将不再出现在登记材料类别和材料时的选项中。用于隐藏不再使用的制造商或形状，同时保留过往登记。",
  "外すと、指示書に紐づける選択肢に出なくなります。": "取消后将不再出现在工单的选项中。",
