  "期間（終了日）": "期间（结束日）",
  "期間を設定するとテンポラリカードになり、期間外はログインできません\n            （終了日はその日いっぱい有効）。1 ユーザーに割当できるカードは 1\n            枚です。": "设置期间后将成为临时卡，期间外无法登录（结束日当天全天有效）。每位用户仅可分配 1 张卡。",
  "期間外のカードはキオスクでログインできません（終了日はその日\n            いっぱい有効）。両方空欄で無期限に戻ります。ログイン中の\n            セッションは最長 8 時間で自然失効します。": "期间外的卡无法在共用终端登录（结束日当天全天有效）。两栏均留空则恢复为无期限。登录中的会话最长 8 小时后自然失效。",
