  "事前承認 = 承認されるまで変更は保留（既定）。事後承認 =\n          変更を即時適用してから承認を回す（差し戻されても工程は自動では\n          戻りません — 指示書詳細に警告が出ます）。": "事前审批 = 变更在批准前保留（默认）。事后审批 = 变更立即应用后再走审批（即使被退回工序也不会自动恢复 — 工单详情中会出现警告）。",
  "事前承認（承認後に適用）": "事前审批（批准后应用）",
