  "実行順はカタログ既定順です（実際の実行可否は工程間依存の解決で決まります）。作業時間 (h) は任意 — 未入力は工程マスタの既定値。社内・外注可の工程は実施場所を選択できます。": "执行顺序为目录默认顺序（实际可否执行由工序间依赖的解析决定）。作业时间 (h) 为可选 — 未填写则使用工序主数据的默认值。允许厂内・外协的工序可选择实施场所。",
  "実行中...": "执行中…",
  "実際に受け取った拠点です。この拠点の在庫が増えますので、荷物が着いた場所を選んでください。": "实际接收的据点。此据点的库存将增加，请选择货物到达的地点。",
  "実際に届いた数です。発注した数と違っても構いません — 分けて届く場合は、届いた分だけを記録します。": "实际到货的数量。与订购数不同也无妨 — 分批送达时仅记录已到货的部分。",
  "実際の届け先（最終需要家）です。ユーザー直送を選んだときは必須で、通常配送でも記録として任意で選べます。": "实际送达地（最终用户）。选择直送最终用户时为必填，常规配送时也可作为记录选填。",
  "実施した作業を担当者・日付ごとに記録します（進行中のみ追加可）。共有端末からの実績には端末の既定作業場所が入ります。": "按负责人・日期记录已实施的作业（仅进行中可添加）。来自共用终端的实绩将填入该终端的默认作业场所。",
