  "書き出したファイル": "导出的文件",
  "書き出したファイル（.txt）に含まれるのは**フォームの作りだけ**です。\n          回答と共有設定は含まれないので、取り込んだフォームは非公開で始まります。\n          受付期間も設定し直してください。": "导出的文件（.txt）仅包含**表单的结构**。不含回答和共享设置，因此导入的表单以不公开状态开始。请同时重新设置受理期间。",
