  "書類（見積書・注文請書・納品書・請求書）": "单据（报价单・订单确认书・送货单・请款单）",
  "書類から会社名を読み取れませんでした。書類を見て選択してください": "无法从单据读取公司名称。请查看单据并选择",
  "書類ごとに、確定の前に通す承認の段を並べます。変更は今後の承認依頼から\n        適用され、進行中の書類は依頼した時点の設定のまま進みます。": "按单据排列确定前需经过的审批级别。变更从今后的审批申请开始生效，进行中的单据将沿用申请时的设置。",
  "書類と見比べて、直すところがあれば「編集」で直してください": "请与单据核对，如需修改请从「编辑」修改",
  "書類なし": "无单据",
  "書類に記載される出荷元の拠点です。在庫保管の出荷書では、この拠点に入庫されます。": "记载在单据上的出货据点。库存保管的出货单将入库至此据点。",
  "書類の言語": "单据语言",
  "書類の注文番号を読み取れませんでした": "无法读取单据的订单编号",
  "書類の内容（金額・種別など）で承認フローを分岐します。上から順に評価し、最初に一致したルールの段構成を既定フローの代わりに使います。どれにも一致しない書類は上の既定フローで進みます。変更は次の承認依頼から有効です。": "根据单据的内容（金额・类别等）分支审批流程。自上而下依次求值，使用首个匹配规则的级别构成代替默认流程。不匹配任何规则的单据将走上方的默认流程。变更从下次审批申请开始生效。",
  "書類の日付を読み取れませんでした": "无法读取单据的日期",
