  "承認に必要なのは、その書類を閲覧または編集できる権限です。書類を\n          開けないメンバーは、承認ボタンを押しても弾かれます。権限は\n          ユーザー管理 (SY01) のロールで決まります。": "审批所需的是查看或编辑该单据的权限。无法打开单据的成员即使按下批准也会被拒绝。权限由用户管理 (SY01) 的角色决定。",
  "承認に必要な権限": "审批所需权限",
