  "承認の段がまだありません。このままだと提出しても承認依頼が始まらず、回答は「提出済」で止まります。「編集」から段を追加してください。": "尚无审批级别。保持现状时即使提交也不会启动审批申请，回答将停留在「已提交」。请从「编辑」添加级别。",
  "承認の段と承認グループは、このフォームの「承認」タブで決めます": "审批级别和审批组在此表单的「审批」标签页中设定",
  "承認の段はこのフォーム専用です。ほかのフォームや書類には影響しません。\n            宛先は承認グループか、この段だけの承認者（カスタム・複数可）から選べます。": "审批级别专属于此表单，不影响其他表单或单据。对象可选审批组，或仅此级别的审批人（自定义・可多名）。",
  "承認の段はまだありません。": "尚无审批级别。",
  "承認の段数と承認者は 承認設定（MS0B）で決めます": "审批级别数和审批人在审批设置 (MS0B) 中确定",
  "承認フロー": "审批流程",
