  "注文請書を選択すると、その注文請書の出荷できる注文明細ごとにグループが追加され、未出荷数量（受注数 − 出荷済）を関連ロットへ自動割付した明細が生成されます（指示書番号順・現物在庫と自明細の取り分の範囲）。ロットは各注文明細に紐づく指示書から選択し、在庫数に対して検証されます。": "选择订单确认书后，将按该订单确认书可出货的订单明细逐一添加分组，并生成将未出货数量（接单数 − 已出货）自动分配到相关批次的明细（按工单编号顺序・在实物库存和本明细份额范围内）。批次从各订单明细关联的工单中选择，并对库存数进行验证。",
