  "直接調達（発注書を経由しない入荷）を登録します。登録と同時に入荷先拠点の素材在庫へ入庫されます。発注入荷は素材発注書の「入荷完了」から自動登録されます。": "登记直接采购（不经采购单的到货）。登记的同时将入库到到货据点的材料库存。采购到货由材料采购单的「入库完成」自动登记。",
  "直送のときの実際の届け先です。出荷書を選ぶと注文請書のエンドユーザーから既定が入ります。": "直送时的实际送达地。选择出货单后将从订单确认书的最终用户填入默认值。",
  "追加": "添加",
