  "通常 … 受注元へ納品します。納品書を荷物に同梱します / ユーザー直送 … 最終需要家へ直接送ります。納品書は別送し、価格は載せないのが通常です。出荷書を選ぶと、注文請書の配送方法から既定が入ります": "常规……送达订货方，送货单随货同附／直送最终用户……直接送达最终用户，送货单另寄，通常不记载价格。选择出货单后将从订单确认书的配送方式填入默认值",
  "通常 か 急ぎ かです。希望納期が入っていればそちらが目安になるので、優先度は「納期は先だが先に手を付けてほしい」といったときに使います。": "普通或加急。若已填写希望交期则以其为参考，优先级用于「交期尚远但希望先着手」等情况。",
